@dataclass(frozen=True)
class ResSFAC:
    # the species list is ordered: an atom record's sfac number is the 1-based
    # index of its species in this list (see the SHELXL manual convention)
    species: tuple[str, ...]
    ions: list[Ion]

    def __str__(self) -> str:
        species = " ".join(f"{specie:<2s}" for specie in self.species)
        ions = "\n".join(map(str, self.ions))
        return f"SFAC {species}\n{ions}\nEND\n"

