@property
def sites(self) -> list[PeriodicSite]:
    """Construct a list of PeriodicSites from the res file.

    Atom records that share the same position (and spin) belong to a single,
    possibly partially occupied site, so they are merged into one PeriodicSite
    with their occupancies summed per species. Sites are returned in order of
    first appearance in the file.
    """
    # (x, y, z, spin) -> ({specie: occupancy}, site properties)
    sites: dict[tuple[Vector3D, float | None], tuple[dict[str, float], dict[str, float] | None]] = {}
    for ion in self._res.SFAC.ions:
        key = (ion.pos, ion.spin)
        species, _ = sites.setdefault(key, ({}, self._site_spin(ion.spin)))
        species[ion.specie] = species.get(ion.specie, 0.0) + ion.occupancy
    return [
        PeriodicSite(species, key[0], self.lattice, properties=props)
        for key, (species, props) in sites.items()
    ]

